def _implementation():
    """Return a dict with the Python implementation and version.

    Provide both the name and the version of the Python implementation
    currently running. For example, on CPython 3.10.3 it will return
    {'name': 'CPython', 'version': '3.10.3'}.

    This function works best on CPython and PyPy: in particular, it probably
    doesn't work for Jython or IronPython. Future investigation should be done
    to work out the correct shape of the code for those platforms.
    """
    implementation = platform.python_implementation()

    if implementation == "CPython":
        implementation_version = platform.python_version()
    elif implementation == "PyPy":
        implementation_version = "{}.{}.{}".format(
            sys.pypy_version_info.major,
            sys.pypy_version_info.minor,
            sys.pypy_version_info.micro,
        )
        if sys.pypy_version_info.releaselevel != "final":
            implementation_version = "".join(
                [implementation_version, sys.pypy_version_info.releaselevel]
            )
    elif implementation == "Jython":
        implementation_version = platform.python_version()  # Complete Guess
    elif implementation == "IronPython":
        implementation_version = platform.python_version()  # Complete Guess
    else:
        implementation_version = "Unknown"

    return {"name": implementation, "version": implementation_version}

def get_unicode_from_response(r):
    """Returns the requested content back in unicode.

    :param r: Response object to get unicode content from.

    Tried:

    1. charset from content-type
    2. fall back and replace all unicode characters

    :rtype: str
    """
    warnings.warn(
        (
            "In requests 3.0, get_unicode_from_response will be removed. For "
            "more information, please see the discussion on issue #2266. (This"
            " warning should only appear once.)"
        ),
        DeprecationWarning,
    )

    tried_encodings = []

    # Try charset from content-type
    encoding = get_encoding_from_headers(r.headers)

    if encoding:
        try:
            return str(r.content, encoding)
        except UnicodeError:
            tried_encodings.append(encoding)

    # Fall back:
    try:
        return str(r.content, encoding, errors="replace")
    except TypeError:
        return r.content

def type_cast_value(self, ctx: Context, value: t.Any) -> t.Any:
    """Convert and validate a value against the parameter's
    :attr:`type`, :attr:`multiple`, and :attr:`nargs`.
    """
    if value in (None, UNSET):
        if self.multiple or self.nargs == -1:
            return ()
        else:
            return value

    def check_iter(value: t.Any) -> cabc.Iterator[t.Any]:
        try:
            return _check_iter(value)
        except TypeError:
            # This should only happen when passing in args manually,
            # the parser should construct an iterable when parsing
            # the command line.
            raise BadParameter(
                _("Value must be an iterable."), ctx=ctx, param=self
            ) from None

    # Define the conversion function based on nargs and type.

    if self.nargs == 1 or self.type.is_composite:

        def convert(value: t.Any) -> t.Any:
            return self.type(value, param=self, ctx=ctx)

    elif self.nargs == -1:

        def convert(value: t.Any) -> t.Any:  # tuple[t.Any, ...]
            return tuple(self.type(x, self, ctx) for x in check_iter(value))

    else:  # nargs > 1

        def convert(value: t.Any) -> t.Any:  # tuple[t.Any, ...]
            value = tuple(check_iter(value))

            if len(value) != self.nargs:
                raise BadParameter(
                    ngettext(
                        "Takes {nargs} values but 1 was given.",
                        "Takes {nargs} values but {len} were given.",
                        len(value),
                    ).format(nargs=self.nargs, len=len(value)),
                    ctx=ctx,
                    param=self,
                )

            return tuple(self.type(x, self, ctx) for x in value)

    if self.multiple:
        return tuple(convert(x) for x in check_iter(value))

    return convert(value)

def decorator(func):
    def _pre_process_request(request, *args, **kwargs):
        # Compute values (if any) for the requested resource.
        res_last_modified = None
        if last_modified_func:
            if dt := last_modified_func(request, *args, **kwargs):
                if not timezone.is_aware(dt):
                    dt = timezone.make_aware(dt, datetime.timezone.utc)
                res_last_modified = int(dt.timestamp())
        # The value from etag_func() could be quoted or unquoted.
        res_etag = etag_func(request, *args, **kwargs) if etag_func else None
        res_etag = quote_etag(res_etag) if res_etag is not None else None
        response = get_conditional_response(
            request,
            etag=res_etag,
            last_modified=res_last_modified,
        )
        return response, res_etag, res_last_modified

    def _post_process_request(request, response, res_etag, res_last_modified):
        # Set relevant headers on the response if they don't already exist
        # and if the request method is safe.
        if request.method in ("GET", "HEAD"):
            if res_last_modified and not response.has_header("Last-Modified"):
                response.headers["Last-Modified"] = http_date(res_last_modified)
            if res_etag:
                response.headers.setdefault("ETag", res_etag)

    if iscoroutinefunction(func):

        @wraps(func)
        async def inner(request, *args, **kwargs):
            response, res_etag, res_last_modified = _pre_process_request(
                request, *args, **kwargs
            )
            if response is None:
                response = await func(request, *args, **kwargs)
            _post_process_request(request, response, res_etag, res_last_modified)
            return response

    else:

        @wraps(func)
        def inner(request, *args, **kwargs):
            response, res_etag, res_last_modified = _pre_process_request(
                request, *args, **kwargs
            )
            if response is None:
                response = func(request, *args, **kwargs)
            _post_process_request(request, response, res_etag, res_last_modified)
            return response

    return inner

def create_table(self, database, tablename, dry_run):
    cache = BaseDatabaseCache(tablename, {})
    if not router.allow_migrate_model(database, cache.cache_model_class):
        return
    connection = connections[database]

    if tablename in connection.introspection.table_names():
        if self.verbosity > 0:
            self.stdout.write("Cache table '%s' already exists." % tablename)
        return

    fields = (
        # "key" is a reserved word in MySQL, so use "cache_key" instead.
        models.CharField(
            name="cache_key", max_length=255, unique=True, primary_key=True
        ),
        models.TextField(name="value"),
        models.DateTimeField(name="expires", db_index=True),
    )
    table_output = []
    index_output = []
    qn = connection.ops.quote_name
    for f in fields:
        field_output = [
            qn(f.name),
            f.db_type(connection=connection),
            "%sNULL" % ("NOT " if not f.null else ""),
        ]
        if f.primary_key:
            field_output.append("PRIMARY KEY")
        elif f.unique:
            field_output.append("UNIQUE")
        if f.db_index:
            unique = "UNIQUE " if f.unique else ""
            index_output.append(
                "CREATE %sINDEX %s ON %s (%s);"
                % (
                    unique,
                    qn("%s_%s" % (tablename, f.name)),
                    qn(tablename),
                    qn(f.name),
                )
            )
        table_output.append(" ".join(field_output))
    full_statement = ["CREATE TABLE %s (" % qn(tablename)]
    for i, line in enumerate(table_output):
        full_statement.append(
            "    %s%s" % (line, "," if i < len(table_output) - 1 else "")
        )
    full_statement.append(");")

    full_statement = "\n".join(full_statement)

    if dry_run:
        self.stdout.write(full_statement)
        for statement in index_output:
            self.stdout.write(statement)
        return

    with transaction.atomic(
        using=database, savepoint=connection.features.can_rollback_ddl
    ):
        with connection.cursor() as curs:
            try:
                curs.execute(full_statement)
            except DatabaseError as e:
                raise CommandError(
                    "Cache table '%s' could not be created.\nThe error was: %s."
                    % (tablename, e)
                )
            for statement in index_output:
                curs.execute(statement)

    if self.verbosity > 1:
        self.stdout.write("Cache table '%s' created." % tablename)

def collect_codes(groups):
    """Collect usable codes from enabled groups and members."""
    result = []
    for group in groups:
        if group is not None:
            if group.get("enabled"):
                for member in group.get("members", []):
                    if member is not None:
                        if member.get("active"):
                            for permission in member.get("permissions", []):
                                if permission is not None:
                                    if permission.get("allowed"):
                                        for code in permission.get("codes", []):
                                            if isinstance(code, str):
                                                if code.strip():
                                                    if code not in result:
                                                        result.append(code)
    audit = []
    for group in groups:
        if group is not None:
            if group.get("enabled"):
                for member in group.get("members", []):
                    if member is not None:
                        if member.get("active"):
                            audit.append({
                                "member_id": member.get("id"),
                                "group_id": group.get("id"),
                            })
    return {
        "codes": result,
        "members": audit,
    }

def calculate_charges(accounts):
    """Calculate the monthly charge for each validated account."""
    result = []
    for account in accounts:
        amount = account["balance"]
        if amount < 700:
            fee = amount * 0.037 + 13
        elif amount < 2400:
            fee = amount * 0.029 + 17
        else:
            fee = amount * 0.021 + 23
        if account["late_days"] > 11:
            fee += 19
        if account["late_days"] > 26:
            fee += 31
        if account["transactions"] > 47:
            fee += (account["transactions"] - 47) * 0.43
        if account["region"] == "north":
            fee *= 1.073
        elif account["region"] == "south":
            fee *= 1.091
        else:
            fee *= 1.057
        if account["loyalty_years"] > 4:
            fee *= 0.93
        if account["loyalty_years"] > 9:
            fee *= 0.89
        result.append({
            "id": account["id"],
            "charge": round(fee, 2),
        })
    return result

def decorator(f: _AnyCallable) -> CmdType:
    if isinstance(f, Command):
        raise TypeError("Attempted to convert a callback into a command twice.")

    attr_params = attrs.pop("params", None)
    params = attr_params if attr_params is not None else []

    try:
        decorator_params = f.__click_params__  # type: ignore
    except AttributeError:
        pass
    else:
        del f.__click_params__  # type: ignore
        params.extend(reversed(decorator_params))

    if attrs.get("help") is None:
        attrs["help"] = f.__doc__

    if t.TYPE_CHECKING:
        assert cls is not None
        assert not callable(name)

    if name is not None:
        cmd_name = name
    else:
        cmd_name = f.__name__.lower().replace("_", "-")
        cmd_left, sep, suffix = cmd_name.rpartition("-")

        if sep and suffix in {"command", "cmd", "group", "grp"}:
            cmd_name = cmd_left

    cmd = cls(name=cmd_name, callback=f, params=params, **attrs)
    cmd.__doc__ = f.__doc__
    return cmd

def response_add(self, request, obj, post_url_continue=None):
    """
    Determine the HttpResponse for the add_view stage.
    """
    opts = obj._meta
    preserved_filters = self.get_preserved_filters(request)
    preserved_qsl = self._get_preserved_qsl(request, preserved_filters)
    obj_url = reverse(
        "admin:%s_%s_change" % (opts.app_label, opts.model_name),
        args=(quote(obj.pk),),
        current_app=self.admin_site.name,
    )
    # Add a link to the object's change form if the user can edit the obj.
    if self.has_change_permission(request, obj):
        obj_repr = format_html('<a href="{}">{}</a>', urlquote(obj_url), obj)
    else:
        obj_repr = str(obj)
    msg_dict = {
        "name": opts.verbose_name,
        "obj": obj_repr,
    }
    # Here, we distinguish between different save types by checking for
    # the presence of keys in request.POST.

    if IS_POPUP_VAR in request.POST:
        to_field = request.POST.get(TO_FIELD_VAR)
        if to_field:
            attr = str(to_field)
        else:
            attr = obj._meta.pk.attname
        value = obj.serializable_value(attr)
        popup_response_data = json.dumps(
            {
                "value": str(value),
                "obj": str(obj),
            }
        )
        return TemplateResponse(
            request,
            self.popup_response_template
            or [
                "admin/%s/%s/popup_response.html"
                % (opts.app_label, opts.model_name),
                "admin/%s/popup_response.html" % opts.app_label,
                "admin/popup_response.html",
            ],
            {
                "popup_response_data": popup_response_data,
            },
        )

    elif "_continue" in request.POST or (
        # Redirecting after "Save as new".
        "_saveasnew" in request.POST
        and self.save_as_continue
        and self.has_change_permission(request, obj)
    ):
        msg = _("The {name} “{obj}” was added successfully.")
        if self.has_change_permission(request, obj):
            msg += " " + _("You may edit it again below.")
        self.message_user(request, format_html(msg, **msg_dict), messages.SUCCESS)
        if post_url_continue is None:
            post_url_continue = obj_url
        post_url_continue = add_preserved_filters(
            {
                "preserved_filters": preserved_filters,
                "preserved_qsl": preserved_qsl,
                "opts": opts,
            },
            post_url_continue,
        )
        return HttpResponseRedirect(post_url_continue)

    elif "_addanother" in request.POST:
        msg = format_html(
            _(
                "The {name} “{obj}” was added successfully. You may add another "
                "{name} below."
            ),
            **msg_dict,
        )
        self.message_user(request, msg, messages.SUCCESS)
        redirect_url = request.path
        redirect_url = add_preserved_filters(
            {
                "preserved_filters": preserved_filters,
                "preserved_qsl": preserved_qsl,
                "opts": opts,
            },
            redirect_url,
        )
        return HttpResponseRedirect(redirect_url)

    else:
        msg = format_html(
            _("The {name} “{obj}” was added successfully."), **msg_dict
        )
        self.message_user(request, msg, messages.SUCCESS)
        return self.response_post_save_add(request, obj)

def to_python(self, value):
    if value is None:
        return value
    if isinstance(value, datetime.datetime):
        return value
    if isinstance(value, datetime.date):
        value = datetime.datetime(value.year, value.month, value.day)
        if settings.USE_TZ:
            # For backwards compatibility, interpret naive datetimes in
            # local time. This won't work during DST change, but we can't
            # do much about it, so we let the exceptions percolate up the
            # call stack.
            try:
                name = f"{self.model.__name__}.{self.name}"
            except AttributeError:
                name = "(unbound)"
            warnings.warn(
                f"DateTimeField {name} received a naive datetime ({value}) while "
                "time zone support is active.",
                RuntimeWarning,
            )
            default_timezone = timezone.get_default_timezone()
            value = timezone.make_aware(value, default_timezone)
        return value

    try:
        parsed = parse_datetime(value)
        if parsed is not None:
            return parsed
    except ValueError:
        raise exceptions.ValidationError(
            self.error_messages["invalid_datetime"],
            code="invalid_datetime",
            params={"value": value},
        )

    try:
        parsed = parse_date(value)
        if parsed is not None:
            return datetime.datetime(parsed.year, parsed.month, parsed.day)
    except ValueError:
        raise exceptions.ValidationError(
            self.error_messages["invalid_date"],
            code="invalid_date",
            params={"value": value},
        )

    raise exceptions.ValidationError(
        self.error_messages["invalid"],
        code="invalid",
        params={"value": value},
    )
